replacements.after:
private var hostWasDestroyed = false

// Campaign: ReactActivityDelegateWrapper can defer the old host's destruction
// until after its replacement resumed. Track identity, not only that callback.
private var lastResumedActivity: WeakReference<Activity>? = null

replacements.before:
// We need to re-register activity contracts when reusing AppContext with new Activity after host destruction.
if (hostWasDestroyed) {
  hostWasDestroyed = false
  registry.registerActivityContracts()
}

activityResultsManager.onHostResume(activity)

replacements.after:
val activityChanged = lastResumedActivity?.let { it.get() !== activity } ?: false
lastResumedActivity = WeakReference(activity)
// Publish the live host before any contract registration can observe it.
activityResultsManager.onHostResume(activity)

// Rebind surviving modules even if the old host's delayed destroy callback
// was ignored by ReactHost after currentActivity had already changed.
if (hostWasDestroyed || activityChanged) {
  hostWasDestroyed = false
  registry.registerActivityContracts()
}
